  ('29c9ed4a-9c0c-44ad-94bf-ccf2e0123d2d', '25303216-75dc-4dbf-93e6-8e646382800c', null, '375624b5-4393-4fc8-8b7e-abc08be3cf60', 'dbf9e481-c077-478a-a248-54328662d9aa', $q$Dune (фильм/франшиза)$q$, 'instagram', 'stories', $q$Кінематографічний едіт всесвіту Дюни$q$, $q$Чорний екран, нарастаюча музика Циммера — і різкий перехід на перший кадр$q$, $q$Крупний план очей Пола Атріда під важкий бас із саундтреку$q$, $j$[{"n": 1, "t_end": 8, "visual": "Чорний екран із появою мінімалістичного титру та стартом гучного басу саундтреку Ханса Циммера", "t_start": 0, "voiceover": "Відчуйте цей масштаб із перших секунд"}, {"n": 2, "t_end": 16, "visual": "Слоу-мо кадр виходу Пола Атріда в пустелі на тлі жовтого піску", "t_start": 8, "voiceover": "Кожен кадр наче окремий витвір мистецтва"}, {"n": 3, "t_end": 23, "visual": "Динамічна склейка польоту орнітоптера крізь бурю на планеті Арракіс", "t_start": 16, "voiceover": "Технології майбутнього у суворому світі"}, {"n": 4, "t_end": 30, "visual": "Фінальний загальний план безкрайніх дюн на заході сонця та логотип фільму", "t_start": 23, "voiceover": "Повертайтеся до цієї естетики щоразу, коли потрібне натхнення"}]$j$::jsonb, $q$Атмосфера Дюни під музику Ханса Циммера$q$, $q$Зібрали добірку атмосферних моментів зі світом Дюни під неперевершений саундтрек Ханса Циммера. Пориньте в кінематографічну естетику пустелі та улюблених героїв.$q$, array[$q$#dune$q$, $q$#duneedits$q$, $q$#timotheechalamet$q$, $q$#zendaya$q$, $q$#hanszimmer$q$, $q$#scifimovides$q$, $q$#cinemaesthetics$q$]::text[], $q$Збережіть стрічку, щоб переглянути ввечері в гарній якості.$q$, 30, $j${"hook": {"score": 90.0, "evidence": "Чорний екран, нарастаюча музика Циммера — і різкий перехід на перший кадр"}, "format_fit": {"score": 50.0, "evidence": "format: stories"}, "uniqueness": {"score": 95.0, "evidence": "Кінематографічний едіт всесвіту Дюни"}, "traceability": {"score": 95.0, "evidence": "Зібрали добірку атмосферних моментів зі світом Дюни під неперевершений саундтрек