insert into public.day4_videos
  (id, content_id, project_id, run_id, niche, title, platform, use_rag, video_model, status, caption, brand_alignment, missing_from_brandbook, frames, segments, video_url, subtitles_vtt, publish_at, approved_by, created_at) values
  ('8c554aa1-374a-4686-8289-829bd1f804f7', 'cec908f8-d189-48c5-9394-1ce647102c74', '65b0053c-c5a0-46f1-9e38-3b6e8c59e51b', '7fb09db3-2328-4ed1-a0eb-448bdcef2224', $q$спешелті-кав'ярня в Києві$q$, $q$Створення індивідуального кавового напою у спешелті барі$q$, 'instagram', true, $q$veo-3.1 · 3/3 сегментів$q$, 'pending_review', $q$Кава має бути такою, як хочеться саме тобі. Збирай свій ідеальний напій на стійці за кілька секунд і насолоджуйся смаком без компромісів. #спешелтікавʼярня #київ #кава #авторськакава$q$, $q$Застосовано правила дружнього та експертного тону з чернетки підпису, збережено фокус на кастомності напою та кав'ярні у Києві. Використано теплу естетику спешелті-бару з акцентом на натуральні текстури.$q$, $q$—$q$, null, $j$[{"n": 1, "duration_sec": 8, "prompt": "Camera slowly pushes in on the stainless steel milk pitcher with creamy oat milk next to the professional espresso machine. Then transitions to golden caramel syrup drops falling into the transparent glass cup with ice cubes on the wooden bar counter. Ambient coffee shop sounds, no spoken words, no text."}, {"n": 2, "duration_sec": 8, "prompt": "Camera smoothly pans as the barista pours an extra espresso shot into the portafilter and tamps the coffee grounds firmly. Ambient background noise of the specialty coffee shop, no spoken words, no text."}, {"n": 3, "duration_sec": 8, "prompt": "Camera slowly pulls back from the ready iced coffee drink with beautiful latte art resting on the warm wooden bar counter. Cozy ambient soundscape of a Kyiv coffee shop, no spoken words, no text."}]$j$::jsonb, $q$/demo/videos/custom-coffee-drink.mp4$q$, E'WEBVTT\n\n1\n00:00.000 --> 00:05.925\nОбирай основу напою: класичне молоко чи рослинна альтернатива\n\n2\n00:06.000 --> 00:11.925\nДодай нотку смаку чи залиш чистий профіль зерна\n\n3\n00:12.000 --> 00:17.925\nРегулюй міцність напою потрійною порцією еспресо\n\n4\n00:18.000 --> 00:23.925\nТвій ідеальний кавовий мікс готовий до насолоди\n', '2026-08-23T15:00:00+00:00', null, '2026-08-23T14:36:13.990313+00:00'),
  ('4018c4aa-ee7b-47a2-87a8-523a120f5a22', '3936ad3d-1c01-4347-9435-b4460bdaa887', '65b0053c-c5a0-46f1-9e38-3b6e8c59e51b', '5949235c-1e02-4e17-bb96-ea385237b505', $q$спешелті-кав'ярня в Києві$q$, $q$Секретний трюк бариста для смачної кави$q$, 'instagram', true, $q$veo-3.1 · 3/3 сегментів$q$, 'approved', $q$Готуєте каву вдома? Ось одна проста звичка від нашого бариста, яка повністю змінить смак вашого ранкового напою. Спробуйте завтра вранці та поділіться враженнями в коментарях! #київськакава #спешелтікава #бариста #рецепткави$q$, $q$Застосовано стиль спешелті-кав'ярні: теплі натуральні відтінки, професійне обладнання та реалістичний світловий патерн. Для підпису використано tone of voice з Day 3 у дружній та експертній формі.$q$, $q$—$q$, null, $j$[{"n": 1, "duration_sec": 8, "prompt": "Smooth camera movement as the barista in a dark green apron looks directly into the camera, smiling confidently and gesturing with his hand. No text on screen, ambient coffee shop background sounds."}, {"n": 2, "duration_sec": 8, "prompt": "The camera slowly pushes in closer as fresh coffee beans fall into the rotary grinder and are ground into the metal portafilter on the scale. No text on screen, ambient grinding sounds."}, {"n": 3, "duration_sec": 8, "prompt": "The camera pulls back slightly to a medium shot as the barista in a dark green apron takes a sip of coffee from a white ceramic cup and nods with satisfaction. No text on screen, ambient coffee shop sounds."}]$j$::jsonb, $q$/demo/videos/barista-secret-trick.mp4$q$, E'WEBVTT\n\n1\n00:00.000 --> 00:07.950\nЗвичка на 10 з 10 для ідеальної кави вдома від нашого бариста.\n\n2\n00:08.000 --> 00:15.950\nЗавжди змелюйте зерно безпосередньо перед заварюванням і зважуйте його на терезах для точної пропорції.\n\n3\n00:16.000 --> 00:23.950\nСпробуйте це завтра вранці, і результат вас приємно здивує.\n', '2026-08-24T15:00:00+00:00', 'admin', '2026-08-23T19:25:41.297863+00:00'),
  ('b93bd037-da79-41ab-9324-c657b8ca39e2', '9bc24edf-8da7-4a03-b02c-dfbd02b4926a', 'c31d278b-a389-4a78-8220-45085ef8b6a3', '7718ffdf-8977-42f3-8c82-98051c7068fe', $q$покемони$q$, $q$Один день з життя магазину карт покемонів$q$, 'tiktok', true, $q$veo-3.1 · 3/3 сегментів$q$, 'approved', $q$Показуємо закулісся нашого робочого дня: від сортування рідкісних голографічних карт до пакування замовлень для колекціонерів. А як проходить ваш вівторок? Поділіться в коментарях! #покемони #tcg #колекціонер #картипокемон #закулісся$q$, $q$Застосовано нейтральний стиль візуального оформлення для затишного магазину колекційних карток, фокус на деталях та атмосфері процесу. У підписі використано чернетку із зазначенням закулісся та процесу пакування замовлень.$q$, $q$—$q$, null, $j$[{"n": 1, "duration_sec": 8, "prompt": "Smooth camera pan down showing hands meticulously sorting shiny holographic pokemon cards by rarity on a wooden desk with warm lighting. Ambient sound of cards sliding."}, {"n": 2, "duration_sec": 8, "prompt": "Dynamic transition to hands placing a phone down, quickly grabbing packing tape and carefully sealing a cardboard box filled with pokemon card sets on a wooden desk. Ambient sound of packing tape."}, {"n": 3, "duration_sec": 8, "prompt": "Gentle camera pull back from a closed shipping box on the desk to reveal the richly stocked shelves filled with pokemon card boxes in the background. Ambient room tone sound."}]$j$::jsonb, $q$/demo/videos/pokemon-shop-day.mp4$q$, E'WEBVTT\n\n1\n00:00.000 --> 00:07.950\nТак виглядає наш звичайний вівторок у світі колекціонерів, починаємо з перевірки нових надходжень.\n\n2\n00:08.000 --> 00:15.950\nДалі узгоджуємо поставки з партнерами та пакуємо колекційні бокси для відправки.\n\n3\n00:16.000 --> 00:23.950\nРобочий день завершено, а замовлення вже їдуть до нових власників.\n', '2026-08-24T15:00:00+00:00', 'admin', '2026-08-23T19:32:49.255208+00:00'),
  ('bc96e1d1-11af-4ad5-a868-1e56587ba642', '29c9ed4a-9c0c-44ad-94bf-ccf2e0123d2d', '25303216-75dc-4dbf-93e6-8e646382800c', '981f6dfe-1b29-4226-a469-75df812a09a6', $q$Dune (фильм/франшиза)$q$, $q$Кінематографічний едіт всесвіту Дюни$q$, 'instagram', true, $q$veo-3.1 · 3/3 сегментів$q$, 'pending_review', $q$Зібрали добірку атмосферних моментів зі світом Дюни під неперевершений саундтрек Ханса Циммера. Пориньте в кінематографічну естетику пустелі та улюблених героїв. #dune #hanszimmer #cinema #arrakis$q$, $q$Використано нейтральну кінематографічну палітру пустелі (жовті, золоті та глибокі бронзові відтінки), м'яке екранне світло заходу сонця та фокус на епічності згідно з загальною тематикою едіту. Тон комунікації у підписі відповідає заданій чернетці з акцентом на атмосферність і музику.$q$, $q$—$q$, null, $j$[{"n": 1, "duration_sec": 8, "prompt": "Slow motion camera movement tracking Paul Atreides as he walks forward against the golden sand of Arrakis, ambient desert wind blowing sand grains, dramatic and epic motion, no text, no recognizable speech."}, {"n": 2, "duration_sec": 8, "prompt": "Dynamic fast-paced camera movement following the ornithopter as it banks sharply and cuts through the swirling dust storm on Arrakis, roaring engine ambient sound, no text, no recognizable speech."}, {"n": 3, "duration_sec": 8, "prompt": "Smooth slow drone shot moving forward over the vast endless dunes of Arrakis towards the setting sun, calm ambient desert wind sound, no text, no recognizable speech."}]$j$::jsonb, $q$/demo/videos/dune-cinematic-edit.mp4$q$, E'WEBVTT\n\n1\n00:00.000 --> 00:05.925\nВідчуйте цей масштаб із перших секунд\n\n2\n00:06.000 --> 00:11.925\nКожен кадр наче окремий витвір мистецтва\n\n3\n00:12.000 --> 00:17.925\nТехнології майбутнього у суворому світі\n\n4\n00:18.000 --> 00:23.925\nПовертайтеся до цієї естетики щоразу, коли потрібне натхнення\n', '2026-08-24T15:00:00+00:00', null, '2026-08-23T20:38:31.046565+00:00')
on conflict (id) do nothing;

